  CONSTRAINT `FK_ct_asiento_cabecera_id_usua` FOREIGN KEY (`id_usuariocrea`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `FK_ct_asientos_cabecera_id_emp` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id`) ON UPDATE CASCADE
